#!/usr/bin/env python3
"""Verify all program overrides generated by GenerateXeFgWmma.ps1."""
import argparse
import csv
import hashlib
from pathlib import Path
from GenerateXeFgCoopMat import KERNELS


def check(root):
    expected = {program: row[0] for row in KERNELS for program in row[-1]}
    seen = set()
    with (root / "wmma_layers.tsv").open(encoding="utf-8-sig", newline="") as stream:
        for row in csv.DictReader(stream, delimiter="\t"):
            program = row["program"]
            if program in seen or expected.get(program) != row["kernel"]:
                raise ValueError(f"Unexpected or duplicate WMMA program: {program}")
            seen.add(program)
            data = (root / f"{program}.dxbc").read_bytes()
            if len(data) < 32 or data[:4] != b"DXBC":
                raise ValueError(f"Invalid DXBC container: {program}")
            if len(data) != int(row["bytes"]) or hashlib.sha256(data).hexdigest() != row["sha256"].lower():
                raise ValueError(f"WMMA size or hash mismatch: {program}")
    if seen != set(expected):
        raise ValueError(f"Missing WMMA programs: {sorted(set(expected) - seen)}")
    print(f"OK: {len(seen)} WMMA overrides verified")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    args = parser.parse_args()
    try:
        check(args.directory)
        check(args.directory / "dot4_split")
    except (OSError, ValueError, KeyError) as exc:
        parser.exit(1, f"error: {exc}\n")
